/**
 * @summary Search universities by name
 */
export const getSearchUniversitiesUrl = (params?: SearchUniversitiesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/universities/search?${stringifiedParams}`
    : `/api/universities/search`;
};

export const searchUniversities = async (
  params?: SearchUniversitiesParams,
  options?: RequestInit,
): Promise<string[]> => {
  return customFetch<string[]>(getSearchUniversitiesUrl(params), {
    ...options,
    method: "GET",
  });
};

